  updateTableValue(value: any) {
    let disTypes = "";
    let da_name = "";
    this.cwsnDiffAbleList.forEach((obj) => {
      disTypes = disTypes
        ? obj.isDisabled
          ? disTypes + "," + (obj.isDisabled ? obj.id : disTypes)
          : disTypes
        : obj.isDisabled
          ? obj.id
          : "";
      da_name = da_name
        ? obj.isDisabled
          ? da_name + "," + (obj.isDisabled ? obj.value : da_name)
          : da_name
        : obj.isDisabled
          ? obj.value
          : "";
    });
    let totalForms = this.formGroupList.get("formGroupPages") as FormArray;
    let currFormTotal =
      totalForms.controls[this.currPage - 1].value.grandParentFA;
    let refTo =
      currFormTotal[currFormTotal.length - 1][
        currFormTotal[currFormTotal.length - 1].controlName
      ];
    let query =
      'UPDATE cwsn_student_list SET ScrSts=1, scrSts_Local="' +
      value +
      '",disabi_types="' +
      disTypes +
      '", refer_to="' +
      this.findReferTo(refTo) +
      '", da_name="' +
      da_name +
      '"' +
      'WHERE StuId = "' +
      this.currStdId +
      '"';
    this.sqliteDB.update(query).then((res) => {
      this.cwsnService.cwsnP1Post("load", 0);
    });

    let newDate = moment(new Date()).format("YYYY-MM-DD");
    let query1 =
      'UPDATE cwsn_student_list SET ScreenedDate="' +
      newDate +
      '"' +
      'WHERE StuId = "' +
      this.currStdId +
      '"';
    this.sqliteDB.update(query1).then((res) => {});
  }
  findReferTo(val: any) {
    if (val == "To Class") {
      val = 1;
    } else if (val == "DEIC") {
      val = 2;
    } else if (val == "Comprehensive Assessment") {
      val = 3;
    }
    return val;
  }

  generatePost(data: any) {
    if (
      parseInt(data.controlName) > 0 &&
      data.ques_type != 3 &&
      data.ques_type != 0
    ) {
      let obj: any = {
        IndxID: data.IndxID,
        Qid: data.controlName,
        ResChar: "",
        isactive: "1",
        ques_type: data.ques_type,
      };
      if (data.ques_type == 12) {
        obj.ResChar = data[data.controlName] ? 1 : 2;
      } else if (data.ques_type == 5) {
        if (data[data.controlName] != undefined) {
          if (data[data.controlName].id != undefined) {
            obj.ResChar = data[data.controlName].id;
          } else {
            obj.ResChar = data[data.controlName];
          }
        } else {
          obj.ResChar = data[data.controlName];
        }
      } else {
        obj.ResChar = data[data.controlName];
      }
      if (obj.ResChar != "") {
        this.formPost.push(obj);
      }
    }
    if (data.subques != undefined) {
      if (data.subques.length > 0) {
        for (let i = 0; i < data.subques.length; i++) {
          this.generatePost(data.subques[i]);
        }
      }
    }
  }

  parsesubques(data: any) {
    for (let i = 0; i < data.length; i++) {
      if (data[i].subFormArray != undefined) {
        if (data[i].subFormArray.length > 0) {
          this.parsesubques(data[i].subFormArray);
        }
      } else if (data[i].subques != undefined) {
        this.generatePost(data[i]);
        if (data[i].subques.length > 0) {
          this.parsesubques(data[i].subques);
        } else {
          this.generatePost(data[i]);
        }
      } else {
        this.generatePost(data[i]);
      }
    }
  }

