import { ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, ViewChild } from '@angular/core';
import { FormArray, FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { UserSessionService } from 'src/app/services/usersession.service';
import { AlertService } from 'src/app/services/alert.service';
import moment from 'moment';
import { IonicSelectableComponent } from 'ionic-selectable';
@Component({
  selector: 'app-aws-dynamic-form1',
  templateUrl: './aws-dynamic-form1.component.html',
  styleUrls: ['./aws-dynamic-form1.component.scss'],
})
export class AwsDynamicForm1Component implements OnInit {


  formArrayList: any = [];
  parentform!: FormGroup;
  @Input() list = '';
  @Input() formGrp: any = FormGroup;
  @Input() formArrName = '';
  @Input() index = '';
  @Input() submitted: any = false;
  @Input() viewstatus: number;
  @Input() healthBlock: any[] = [];
  

  @Output()
  childDom = new EventEmitter<{}>();

  cateID: any = '';
  sub: boolean = false;
  listFromApi: any = [];
  teacherTable: boolean = true;
  cattyId: any = "";
  schoolTyId: any;
  teachId: any;
  currentYear: any;
  maxDate:any = '2040-01-01';
  previousYear: number;
  currPageParam: any = 1;
  currControl: any = '';
  diable1 :boolean = false;

  quesIndex: any = 0;
  classType: any = 1;
  minFmDate:any = new Date();
  @ViewChild('dischargingPortsComponent')
  dischargingPortsComponent: IonicSelectableComponent;
  data: any;
  isDrpDwnChange:boolean = false;

  constructor(private route: ActivatedRoute, private fb: FormBuilder, private userSessionService: UserSessionService,
    private cdr: ChangeDetectorRef, private alertService: AlertService) {
    this.currentYear =  moment(new Date()).format('YYYY-MM-DD');
    this.previousYear = this.currentYear - 1;

  }


  ngOnInit(): void {
    this.route.queryParams.subscribe((params) => {
      this.currPageParam = params['id'];
      this.classType = params['class'];
      this.classType = 'this.classType.toString()';
    });
    // if(this.viewstatus ==1){

    //   this.diable1 = false
    // }else{
    //   this.diable1 =true
    // }
    this.listFromApi = localStorage.getItem("listFromApi") ? JSON.parse(localStorage.getItem("listFromApi")) : [];
    this.parentform = this.createFormArray();
    this.updateItemsToformArray();
    let formArr: any = this.parentform.get('dynamicFormArray');
    if (this.formArrName == 'grandParentFA') {
      for (let i = 0; i < formArr.controls.length; i++) {
        (this.formGrp.get(this.formArrName)).push(formArr.controls[i]);
      }
    } else {
      // ======bind subforms to parent form======
      this.formGrp = this.formGrp.controls;
      for (let i = 0; i < formArr.controls.length; i++) {
        this.formGrp[Number(this.index)].controls.subques.push(formArr.controls[i]);
      }
    };
    this.cdr.detectChanges();
  }

  ngAfterViewInit() {
    let parForm: any = this.parentform.get('dynamicFormArray');
    // this.childDom.emit(parForm);
    this.cdr.detectChanges();
    this.data = window.localStorage.getItem("viewstatus");
    if(this.data == 1){
      this.diable1 = false
      this.cdr.detectChanges();
    }else{
      this.diable1 = true
      this.cdr.detectChanges();
    }

    console.log(this.healthBlock, 'healthBlock');
    
 
  }

  ionViewDidEnter() {
    this.cdr.detectChanges();
  }

  createFormArray() {
    return this.fb.group({
      dynamicFormArray: this.fb.array([])
    })
  }

  mainQuesChange(controlName, event){
    let obj = {
      qId: controlName,
      value: event.detail.value
    };
    this.childDom.emit(obj);
    this.cdr.detectChanges();
  }

  updateItemsToformArray() {
    this.formArrayList = this.parentform.get('dynamicFormArray') as FormArray;    
    let data: any = this.list;
    if (data?.length > 0) {
      this.quesIndex = 0;
      for (let i = 0; i < data.length; i++) {
        if (data[i].subques.length > 0) {
          data[i].subquesList = data[i].subques;
        } else if (!(data[i].subquesList)) {
          data[i].subquesList = [];
        }
        (data[i].subquesList).forEach(element => {
          element['mainQuesInd'] = i;
        });
        let obj: any={};
        obj = {
          ques_id: new FormControl(i, null),
          ques_displayid: new FormControl(data[i].ques_displayid, null),
          ques_text: new FormControl(data[i].ques_text, null),
          ques_type: new FormControl(data[i].ques_type, null),
          table_footer_text: new FormControl(data[i].table_footer_text, null),
          ques_valid: new FormControl(data[i].ques_valid, null),
          ques_option: new FormControl(data[i].ques_option, null),
          controlName: new FormControl(data[i].controlName),
          subquesLength: new FormControl(data[i].subquesList.length),
          subques: this.fb.array([]),
          subquesList: new FormControl(data[i].subquesList),
          col: new FormControl(data[i].col),
          value: new FormControl(data[i].value),
          table: new FormControl(data[i].table),
          notes: new FormControl(data[i].info),
          emsg: new FormControl(data[i].info),
          disable: new FormControl(data[i].disable),
          hidden: new FormControl(data[i].hidden),
          expected: new FormControl(data[i].expected),
          cls_name: new FormControl(data[i].cls_name),
          ques_tamil: new FormControl(data[i].ques_tamil),
          ques_english: new FormControl(data[i].ques_english),
          label1: new FormControl(data[i].label1),
          label2: new FormControl(data[i].label2),
          Screened_Dis_type: new FormControl(data[i].Screened_Dis_type),
          calcSubValid: new FormControl(data[i].calcSubValid),
          grp_type: new FormControl(data[i].grp_type),
          sub_heading: new FormControl(data[i].sub_heading),
          ques_text_type: new FormControl(data[i].ques_text_type),
          page: new FormControl(data[i].page),
          mainQuesInd: new FormControl(data[i]?.mainQuesInd),
          option_mapping: new FormControl(data[i]?.option_mapping,null)
        };
        if (data[i].ques_type == 0) {
          obj[data[i].controlName] = new FormControl('');
        } else if (data[i].ques_type == 1) {
          obj[data[i].controlName] = !(data[i].hidden) ? new FormControl('', [Validators.required]) : new FormControl('');
        } else if (data[i].ques_type == 2) {
          obj[data[i].controlName] = (data[i].required == 1) ? new FormControl('', [Validators.required, Validators.pattern(data[i].pattern)]) : new FormControl('');
        } else if (data[i].ques_type == 3) {
          obj[data[i].controlName] = new FormControl('');
        }else if (data[i].ques_type == 4) {
          obj[data[i].controlName] = (data[i].required == 1) ? new FormControl('', [Validators.required]) : new FormControl('');
        }  else if (data[i].ques_type == 5) {
          obj[data[i].controlName] = new FormControl('', [Validators.required]);
        } else if (data[i].ques_type == 6) {
          obj[data[i].controlName] = new FormControl('', [Validators.required]);
        }
        else if (data[i].ques_type == 7) {
          obj[data[i].controlName] = new FormControl('', [Validators.required]);
        } 
        else if (data[i].ques_type == 8) {
          obj[data[i].controlName] = (data[i].required == 1) ? new FormControl('', [Validators.required]) : new FormControl('');
        }
        else {
          obj[data[i].controlName] = new FormControl('');
        }

        if(this.listFromApi.length == 0 && data[i].ques_type == 1){
          data[i].value = '2';
        }
        for (let k = 0; k < this.listFromApi.length; k++) {
          let list: any = this.listFromApi[k];
          if (list) {
            if (data[i].controlName == list.Qid) {
              if (data[i].ques_type == 5) {
                let dropValue = data[i].ques_option.find(obj => obj.id == list.ResChar);
                data[i].value = dropValue?.id;
              } else  if (data[i].ques_type == 6) {
                let res = list.ResChar.split(',');
                let dropValue = [];
                data[i].ques_option.forEach(obj => {
                  if(res.includes(obj.id)) {
                    dropValue.push(obj);
                  }
                });
                data[i].value = dropValue;
              }  else if (data[i].ques_type == 12) {
                data[i].value = list.ResChar == '1' ? true : false;
              } else if (data[i].ques_type == 16) {
                let dropValue = data[i].ques_option.find(obj => obj == list.ResChar);
                data[i].value = dropValue;
              } else if (data[i].ques_type == 6) {
                let valSplit = list.ResChar.split(',');
                let dropValue = valSplit;
                data[i].value = dropValue;
              } else {
                data[i].value = list.ResChar;
              }
            }
          }
        }
        if (this.listFromApi[this.listFromApi.length - 1]?.stdType) {
          data[i].value = '';
        }
        this.formArrayList.push(this.fb.group(obj));
        this.formArrayList.controls[i].patchValue({
          [data[i].controlName]: data[i].value,
        });
        this.formArrayList.controls[i].updateValueAndValidity();
        
      }
    }
  }

  dynamicPatchValue(index: any, formIndex: any) {
    this.formArrayList.controls[formIndex].patchValue({
      [this.list[index]['controlName']]: this.list[index]['value'],
    });
    this.formArrayList.controls[formIndex].updateValueAndValidity();
  }

  removeFormControl(index: any) {
    // this.formArrayList.controls[index].controls.clear();
  }

  removeSubQues(list: any) {
    list.controls.subques.clear();
  }

  removeSubQuesCond(list: any, currVal) {
    let temp= [];
    if(list['controls']) { 
      let qstList= list['controls'].subques.value;
       temp = qstList.filter((obj:any, idx)=>{
         return obj.option_mapping && obj.option_mapping!=currVal; 
       });
       if(temp) {
        debugger
        temp.forEach(obj1=>{
          let idx = qstList.findIndex((obj2:any)=>{return obj2.controlName==obj1.controlName});
          if(idx!=-1) {
              list.controls.subques.removeAt(idx);
          }
        });
       }
    };
  
    // list.controls.subques.clear();
  }
  showSubQuesDropdown(expected: any, current: any) {
    if (expected.includes(current)) {
      return true;
    } else {
      return false;
    }
  }
  setFormValidation(list: any, val: any, index: any, loopArr: any) {
    // if(this.viewstatus == 2){
    //   this.truevalue1 = true
    // }
    // else{
    //   this.truevalue2 = true
    // }
    
    let isAllValid: boolean = true;
    if (loopArr[index - 1]?.valid || index == 0) {
      for (let j = 0; j < loopArr.length; j++) {
        if (j != index) {
          loopArr[j].patchValue({
            [loopArr[j].controls.controlName.value]: false
          });
        }
      };
      list.patchValue({
        [list.controls.controlName.value]: val
      });
    } else {
      for (let i = 0; i < loopArr.length; i++) {
        if (loopArr[i].invalid) {
          this.alertService.warning("Please fill all questions in section " + (i+1));
          for (let j = 0; j < loopArr.length; j++) {
            if (j != i) {
              loopArr[j].patchValue({
                [loopArr[j].controls.controlName.value]: false
              });
            }
          };
          loopArr[i].patchValue({
            [loopArr[i].controls.controlName.value]: val
          });
          isAllValid = false;
          return;
        }
      }
    };

    if (isAllValid) {
      list.patchValue({
        [list.controls.controlName.value]: val
      });
    }
  }

  subQustShowCond(list:any, currVal:any) {
    let temp= [];
    if(list['controls']) { 
      let qstList= list['controls'].subquesList.value;
       temp = qstList.filter((obj:any)=>{
         return !obj.option_mapping || obj.option_mapping==currVal; 
       });
    };
    return temp.length>0?temp:list;
  };
}
