checkMutiDisLabel(list:any) {
  if(list.length > 1){
    this.isMultiple = true;
  }else{
    this.isMultiple = false;
  }
  if(list.includes('Multiple Disabilities பல்வகைத்திறன் குறைபாடு')) {
    return true;
  } else {
    return false;
  };
}

checkDefBlind(list:any) {
  if(list.includes('Visual Impairment - பார்வைத்திறன் குறைபாடு') && list.includes('Hearing Impairment - செவித்திறன் குறைபாடு') && list.length ==3) {
    return true;
  } else {
    return false;
  }; 
}


 intToRoman(num) {
  let map:any = {
    M: 1000,
    CM: 900,
    D: 500,
    CD: 400,
    C: 100,
    XC: 90,
    L: 50,
    XL: 40,
    X: 10,
    IX: 9,
    V: 5,
    IV: 4,
    I: 1,
  };
  let result = '';
  
  for (let key in map) {  
    const repeatCounter = Math.floor(num / map[key]);
    if (repeatCounter !== 0) {
      result += key.repeat(repeatCounter);
    }
    num %= map[key];
    if (num === 0) return result;
  }
  
  return result;
};

